import 'bootstrap/dist/css/bootstrap.min.css';
import {createIcons,Layers3,LayoutDashboard,Library,Route,Award,Trophy,Orbit,ChartNoAxesCombined,Goal,UserRound,Settings2,ShieldCheck,Sparkles,LogOut,Menu,Search,Zap,Bell,ArrowUpRight,X,ArrowRight,Gem,CalendarDays,CircleCheck,Flame,Clock3,Check,Circle,Braces,Database,CodeXml,BookOpen,ArrowLeft,Lock,Flag,Play,Lightbulb,SkipForward,CircleX,GraduationCap,Crown,CalendarCheck,Compass,Layers,Globe,Download,Printer,Plus,Pencil,Trash2,WifiOff,Target,Eye,EyeOff,UsersRound,Copy} from 'lucide';
import Chart from 'chart.js/auto';
import './style.css';
import {t,locale,languageSelect,localize,observeTranslations,errorText} from './i18n';
import {themeControl,applyPreferences} from './preferences';
import {request} from './request';
import {createRequestId} from './request-id';
import {practiceForm,practiceAnswer} from './practice-form';
import {showPage,settingsMarkup,wireShowSettings,prepareShowEntryAudio,cancelShowEntryAudio} from './show';

const app=document.querySelector('#app');
const icons={Layers3,LayoutDashboard,Library,Route,Award,Trophy,Orbit,ChartNoAxesCombined,Goal,UserRound,Settings2,ShieldCheck,Sparkles,LogOut,Menu,Search,Zap,Bell,ArrowUpRight,X,ArrowRight,Gem,CalendarDays,CircleCheck,Flame,Clock3,Check,Circle,Braces,Database,CodeXml,BookOpen,ArrowLeft,Lock,Flag,Play,Lightbulb,SkipForward,CircleX,GraduationCap,Crown,CalendarCheck,Compass,Layers,Globe,Download,Printer,Plus,Pencil,Trash2,WifiOff,Target,Eye,EyeOff,UsersRound,Copy};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ui=key=>key;
const num=n=>new Intl.NumberFormat(locale()).format(n??0);
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
let accessToken='',accessTokenExpiresAt=0,role='',me=null,refreshing=null,activeTask=null,timer=null,charts=[];
let refreshToken=sessionStorage.getItem('refreshToken')||localStorage.getItem('refreshToken')||'';
let thresholds=[0,500,1200,2500,5000,9000,15000,25000];
let routeVersion=0,disposePage=null;
const nav=[['dashboard','layout-dashboard','Dashboard'],['show','play','Лига знаний · 3D-шоу'],['courses','library','Courses'],['learning','route','My Learning'],['achievements','award','Achievements'],['leaderboard','trophy','Leaderboard'],['seasons','orbit','Seasons'],['statistics','chart-no-axes-combined','Statistics'],['daily-goals','goal','Daily Goals'],['profile','user-round','Profile'],['settings','settings-2','Settings']];
const adminNav=[['dashboard','layout-dashboard','Dashboard'],['students','users-round','Students'],['courses','library','Courses'],['levels','layers','Levels'],['topics','book-open','Topics'],['tasks','circle-check','Tasks'],['achievements','award','Achievements'],['seasons','orbit','Seasons'],['daily-goals','goal','Daily Goals'],['reports','chart-no-axes-combined','Reports'],['ai-settings','sparkles','AI Settings'],['settings','settings-2','Settings']];
function navigation(){return role==='ADMIN'?adminNav:nav;}
function navHref(id){return role==='ADMIN'&&id!=='settings'?'#admin?resource='+(id==='ai-settings'?'settings':id):'#'+id;}
function activeNav(route){if(role==='ADMIN'&&route==='admin'){const resource=new URLSearchParams(location.hash.split('?')[1]).get('resource')||'dashboard';return resource==='settings'?'ai-settings':resource;}return route;}
function toast(message,type='info'){const el=document.createElement('div');el.className=`toast-message ${type}`;el.textContent=t(message);document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),5000);}
function hydrate(){createIcons({icons});localize();}
function saveSession(response,remember){accessToken=response.accessToken;accessTokenExpiresAt=Date.now()+(response.expiresIn||900)*1000;role=response.role;refreshToken=response.refreshToken;
 const persistent=remember??!!localStorage.getItem('refreshToken');localStorage.removeItem('refreshToken');sessionStorage.removeItem('refreshToken');(persistent?localStorage:sessionStorage).setItem('refreshToken',refreshToken);}
async function refresh(force=false){if(!force&&accessToken&&Date.now()<accessTokenExpiresAt-30000)return;if(!refreshToken)throw Error(t('sessionExpired'));if(!refreshing)refreshing=api('auth/refresh',{method:'POST',body:{refreshToken}},false).then(result=>saveSession(result)).finally(()=>refreshing=null);return refreshing;}
async function api(path,options={},retry=true){let r,text;try{const result=await request('/api/'+path,{...options,headers:{'Content-Type':'application/json',...(accessToken?{Authorization:'Bearer '+accessToken}:{}),...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});r=result.response;text=result.text;}catch{throw Error(t('serverUnavailable'));}
 if(r.status===401&&retry&&!path.startsWith('auth/')){try{await refresh(true);return api(path,options,false);}catch{clearSession();location.hash='login';throw Error(t('sessionExpired'));}}
 let data;try{data=text?JSON.parse(text):{};}catch{throw Error(t('serverUnavailable'));}
 if(!r.ok)throw Object.assign(new Error(errorText(data,r.status)),{fields:data.errors||[],code:data.code||(path==='auth/login'&&r.status===401?'invalidCredentials':'')});return data;}
function clearSession(){accessToken='';accessTokenExpiresAt=0;refreshToken='';role='';me=null;sessionStorage.removeItem('refreshToken');localStorage.removeItem('refreshToken');sessionStorage.removeItem('gameRoom');}
const post=(path,body={})=>api(path,{method:'POST',body});
function progress(value,max){return `<div class="progress-track" role="progressbar" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${max||1}"><span style="width:${Math.max(0,Math.min(100,value/(max||1)*100))}%"></span></div>`;}
function date(value,style='numeric'){return `<time data-date="${esc(new Date(value).toISOString())}" data-date-style="${style}">${new Intl.DateTimeFormat(locale(),style==='short'?{month:'short',day:'numeric',timeZone:'Asia/Qyzylorda'}:{timeZone:'Asia/Qyzylorda'}).format(new Date(value))}</time>`;}
function updateDates(){document.querySelectorAll('[data-date]').forEach(el=>el.textContent=new Intl.DateTimeFormat(locale(),el.dataset.dateStyle==='short'?{month:'short',day:'numeric',timeZone:'Asia/Qyzylorda'}:{timeZone:'Asia/Qyzylorda'}).format(new Date(el.dataset.date)));for(const c of charts)if(c.labelDates){c.data.labels=c.labelDates.map(value=>new Intl.DateTimeFormat(locale(),{weekday:'short'}).format(new Date(value+'T12:00:00Z')));c.update();}}
function initials(s){return esc((s.firstName?.[0]??'')+(s.lastName?.[0]??''));}
function avatar(s){return s.avatarUrl&&s.avatarUrl.startsWith('https://')?`<img class="avatar" src="${esc(s.avatarUrl)}" alt="${esc(s.firstName)}" width="40" height="40">`:`<span class="avatar">${initials(s)}</span>`;}
function button(text,href,secondary=false){return `<a class="btn ${secondary?'btn-secondary':'btn-primary'}" href="${href}">${text}${icon('arrow-up-right')}</a>`;}
function header(kicker,title,description,action=''){return `<header class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</header>`;}
function shell(route){return `<aside class="sidebar"><a href="#dashboard" class="brand"><span class="brand-mark">${icon('layers-3')}</span>ascend<span class="brand-dot">.</span></a><div class="workspace-label">YOUR LEARNING SPACE</div><nav aria-label="Main navigation">${navigation().map(([id,i,label])=>`<a href="${navHref(id)}" class="nav-item ${activeNav(route)===id?'active':''}">${icon(i)}<span>${label}</span>${id==='courses'?'<small>03</small>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="season-mini">${icon('sparkles')}<span>Small steps. Real progress.<small>Your next level starts here.</small></span></div><button id="logout" class="nav-item">${icon('log-out')}Sign Out</button></div></aside><div class="main-wrap"><header class="topbar"><button class="icon-button mobile-toggle" id="menu-toggle" aria-label="Toggle navigation">${icon('menu')}</button><label class="searchbox">${icon('search')}<input id="global-search" type="search" placeholder="Find your next course…" aria-label="Search courses"><kbd>/</kbd></label><div class="topbar-right">${languageSelect()}${themeControl()}${me?`<span class="top-xp">${icon('zap')} ${num(me.totalXP)} XP</span><span class="level-pill">LVL ${me.level}</span><button id="notifications" class="icon-button" aria-label="Notifications">${icon('bell')}</button><a href="#profile" class="profile-link">${avatar(me)}</a>`:'<span class="level-pill">ADMIN STUDIO</span>'}</div></header><main id="content" tabindex="-1"><div class="loading-grid" aria-label="Loading"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></main><footer class="app-footer"><span>ASCEND ACADEMY</span><span>Learn a little. Become a lot.</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${navigation().slice(0,5).map(([id,i,label])=>`<a href="${navHref(id)}" class="${activeNav(route)===id?'active':''}" aria-label="${label}">${icon(i)}<small>${id==='learning'?'Learn':label}</small></a>`).join('')}</nav>`;}
function wireShell(){document.querySelector('#logout').onclick=async()=>{try{await post('auth/logout',{refreshToken});}catch{}clearSession();location.hash='login';};
 document.querySelector('#menu-toggle').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
 const search=document.querySelector('#global-search');search.onkeydown=e=>{if(e.key==='Enter')location.hash='courses?q='+encodeURIComponent(search.value);};
 document.querySelector('#notifications')?.addEventListener('click',async()=>{try{const notifications=await api('notifications');showDialog('Your notifications',notifications.length?notifications.map(n=>`<div class="notification"><strong>${esc(n.title)}</strong><p data-learning-content>${esc(n.message)}</p></div>`).join(''):'<p>You are all caught up. New achievements will appear here.</p>');await post('notifications/read');}catch(e){toast(e.message,'error');}});
}
function showDialog(title,body){const d=document.querySelector('#celebration');d.innerHTML=`<button class="dialog-close icon-button" aria-label="Close">${icon('x')}</button><h2 id="celebration-title">${title}</h2>${body}<button class="btn btn-primary dialog-done">Continue ${icon('arrow-right')}</button>`;d.querySelector('.dialog-close').onclick=()=>d.close();d.querySelector('.dialog-done').onclick=()=>d.close();d.showModal();hydrate();}
function celebrate(result,oldLevel){if(result.level>oldLevel||result.achievements.length){showDialog(result.level>oldLevel?`Level ${result.level}. Unlocked.`:'Achievement unlocked!',`<div class="celebration-badge">${icon(result.level>oldLevel?'gem':'trophy')}</div><div class="reward-big">+${num(result.xpEarned)} XP</div>${result.achievements.map(a=>`<p><strong>${esc(a.title)}</strong> · +${a.xpReward} XP</p>`).join('')}<p>Keep going. Your effort is adding up.</p>`);const d=document.querySelector('#celebration');for(let i=0;i<25;i++){const particle=document.createElement('span');particle.className='confetti';particle.style.setProperty('--x',Math.random()*100+'%');particle.style.setProperty('--delay',Math.random()*.4+'s');d.append(particle);}}}
function chart(canvas,type,labels,datasets){if(!canvas)return;charts.push(new Chart(canvas,{type,data:{labels,datasets},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:datasets.length>1,labels:{color:'#b9b1cf'}}},scales:type==='doughnut'?{}:{x:{grid:{display:false},ticks:{color:'#9288a9'}},y:{beginAtZero:true,grid:{color:'#ffffff08'},ticks:{color:'#9288a9',precision:0}}}}}));}

function passwordField(name,label,autocomplete){return `<label for="${name}">${ui(label)}</label><div class="password-field"><input id="${name}" name="${name}" type="password" autocomplete="${autocomplete}" maxlength="128" required aria-describedby="${name}-error"><button type="button" class="password-toggle icon-button" data-password="${name}" aria-label="${ui('Show password')}" aria-pressed="false">${icon('eye')}</button></div><p class="field-error" id="${name}-error" data-error-for="${name}" role="status"></p>`;}
function authValidation(fields,register,reset,forgot){
 const errors=[];const add=(field,code)=>errors.push({field,code});
 if(register){for(const [field,code] of [['firstName','firstNameRequired'],['lastName','lastNameRequired']]){if(!fields[field]?.trim())add(field,code);else if(fields[field].length>80)add(field,'nameTooLong');}}
 if(!reset){if(!fields.email?.trim())add('email','emailRequired');else if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fields.email)||fields.email.length>191)add('email','emailInvalid');}
 if(!forgot){if(!fields.password)add('password','passwordRequired');else if(fields.password.length>128)add('password','passwordLong');else if(register||reset){if(fields.password.length<8)add('password','passwordShort');else if(!/[A-Z]/.test(fields.password)||!/[a-z]/.test(fields.password)||!/[0-9]/.test(fields.password)||! /[^a-zA-Z0-9]/.test(fields.password))add('password','passwordRules');}}
 if(register||reset){if(!fields.confirmPassword)add('confirmPassword','confirmRequired');else if(fields.confirmPassword!==fields.password)add('confirmPassword','passwordMismatch');}return errors;
}
async function authPage(mode){
 const register=mode==='register',forgot=mode==='forgot',reset=mode==='reset';
 app.innerHTML=`<div class="auth-layout"><section class="auth-story"><a class="brand" href="#login"><span class="brand-mark">${icon('layers-3')}</span>ascend<span class="brand-dot">.</span></a><div class="auth-story-content"><div class="eyebrow">${ui('A NEW WAY TO LEVEL UP')}</div><h1>${ui('Learn with purpose.')}<br>${ui('Play for progress.')}</h1><p>${ui('Your personal learning journey, powered by adaptive challenges. Build skills, unlock achievements, and make every day count.')}</p><div class="crystal-scene"><div class="crystal"><span></span><span></span><span></span></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="floating-label">${icon('zap')} ${ui('YOUR NEXT LEVEL')}</span></div><div class="auth-benefits"><span>${icon('route')}${ui('Your own learning path')}</span><span>${icon('sparkles')}${ui('Adaptive challenges')}</span><span>${icon('award')}${ui('Progress you can see')}</span></div></div><small>GAMIFIED LEARNING SYSTEM / ASCEND ACADEMY</small></section><section class="auth-form-side"><div class="auth-language">${languageSelect()}${themeControl()}</div><div class="auth-form-wrap"><span class="tag">${icon('sparkles')} ${ui('MAKE PROGRESS YOUR HABIT')}</span><h2>${ui(register?'Start your journey':forgot?'Reset your password':reset?'Choose a new password':'Welcome back')}</h2><p>${ui(register?'Your next chapter starts with one small step.':forgot?'We will deliver a reset link for your account.':reset?'Use at least 8 characters, including uppercase and lowercase letters, a number and a symbol.':'Ready for your next challenge? Let’s pick up where you left off.')}</p><form id="auth-form" novalidate>${register?`<div class="form-row"><div><label for="firstName">${ui('First name')}</label><input id="firstName" name="firstName" autocomplete="given-name" required maxlength="80" aria-describedby="firstName-error"><p id="firstName-error" class="field-error" data-error-for="firstName"></p></div><div><label for="lastName">${ui('Last name')}</label><input id="lastName" name="lastName" autocomplete="family-name" required maxlength="80" aria-describedby="lastName-error"><p id="lastName-error" class="field-error" data-error-for="lastName"></p></div></div>`:''}${!reset?`<label for="email">${ui('Email address')}</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="191" aria-describedby="email-error"><p id="email-error" class="field-error" data-error-for="email"></p>`:''}${!forgot?passwordField('password','Password',register||reset?'new-password':'current-password'):''}${register||reset?`<p class="password-help">${ui('Use at least 8 characters, including uppercase and lowercase letters, a number and a symbol.')}</p>${passwordField('confirmPassword','Confirm password','new-password')}`:''}${!register&&!forgot&&!reset?`<div class="form-meta"><label class="checkbox"><input name="rememberMe" type="checkbox">${ui('Remember me')}</label><a href="#forgot">${ui('Forgot password?')}</a></div>`:''}<p id="auth-error" role="alert" class="form-error"></p><button class="btn btn-primary w-100" type="submit">${ui(register?'Create Account':forgot?'Send Reset Link':reset?'Update Password':'Sign In')}${icon('arrow-right')}</button></form><p class="auth-switch">${register?`${ui('Already learning with us?')} <a href="#login">${ui('Sign in')}</a>`:forgot||reset?`<a href="#login">${ui('Back to sign in')}</a>`:`${ui('New to Ascend?')} <a href="#register">${ui('Create an account')}</a>`}</p>${!register&&!forgot&&!reset?`<details class="demo-accounts"><summary>${ui('University demo accounts')}</summary><p>${ui('Student:')} <span data-user-content>student@example.com / Student123!</span><br>${ui('Admin:')} <span data-user-content>admin@example.com / Admin123!</span></p></details>`:''}<div class="auth-note">${icon('shield-check')}${ui('Your progress is safely stored in your account.')}</div></div></section></div>`;
 app.querySelectorAll('[data-password]').forEach(button=>button.onclick=()=>{const input=document.getElementById(button.dataset.password),visible=input.type==='password';input.type=visible?'text':'password';button.setAttribute('aria-label',t(visible?'Hide password':'Show password'));button.setAttribute('aria-pressed',String(visible));button.innerHTML=icon(visible?'eye-off':'eye');hydrate();});
 const form=document.querySelector('#auth-form');
 function showErrors(errors,message=''){form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));form.querySelectorAll('[data-error-for]').forEach(el=>el.textContent='');for(const error of errors){const field=error.field[0].toLowerCase()+error.field.slice(1),input=form.elements.namedItem(field),label=form.querySelector(`[data-error-for="${field}"]`);input?.setAttribute('aria-invalid','true');if(label)label.textContent=t(error.code);}document.querySelector('#auth-error').textContent=message||[...new Set(errors.map(e=>t(e.code)))].join(' ');if(errors.length){const field=errors[0].field;form.elements.namedItem(field[0].toLowerCase()+field.slice(1))?.focus();}}
 hydrate();form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button[type=submit]');if(b.disabled)return;showErrors([]);const fields=Object.fromEntries(new FormData(form)),errors=authValidation(fields,register,reset,forgot);if(errors.length){showErrors(errors);return;}b.disabled=true;try{
 if(forgot){const r=await post('auth/forgot-password',{email:fields.email});toast(r.message);location.hash='login';}
 else if(reset){const token=new URLSearchParams(location.hash.split('?')[1]).get('token');const r=await post('auth/reset-password',{token,password:fields.password,confirmPassword:fields.confirmPassword});toast(r.message,'success');location.hash='login';}
 else{const remember=!!fields.rememberMe;const payload=register?{...fields,firstName:fields.firstName.trim(),lastName:fields.lastName.trim()}: {email:fields.email,password:fields.password,rememberMe:remember};const response=await post('auth/'+(register?'register':'login'),payload);saveSession(response,remember);location.hash=role==='ADMIN'?'admin':'dashboard';}
 }catch(err){showErrors(err.fields?.length?err.fields:err.code==='invalidCredentials'?[{field:'email',code:'invalidCredentials'},{field:'password',code:'invalidCredentials'}]:[],err.message);}finally{b.disabled=false;}};
}
function courseCard(c){const symbols={csharp:'braces',sql:'database',web:'code-xml'};return `<article class="course-card"><div class="course-art ${esc(c.id)}"><span class="course-symbol">${icon(symbols[c.id]||'book-open')}</span><span class="course-art-grid"></span><span class="course-category">${esc(c.category)}</span></div><div class="course-card-body"><div class="course-meta"><span class="difficulty">${esc(c.difficulty)}</span><span>${icon('clock-3')}${c.estimatedMinutes} min</span></div><h3 data-learning-content>${esc(c.title)}</h3><p data-learning-content>${esc(c.description)}</p><div class="course-progress-label"><span>${c.completed?'Your progress':'Ready when you are'}</span><strong>${Math.round(c.completed/(c.taskCount||1)*100)}%</strong></div>${progress(c.completed,c.taskCount)}<div class="course-card-bottom"><span>${icon('zap')}${num(c.totalXP)} XP</span><a href="#course/${esc(c.id)}">${c.completed?'Continue Learning':'Explore Course'}${icon('arrow-right')}</a></div></div></article>`;}
async function dashboard(content){const [stats,list,goals,achievements,board,recommendation]=await Promise.all([api('statistics'),api('courses'),api('daily-goals'),api('achievements'),api('leaderboard?period=weekly'),api('ai/next-task').catch(()=>null)]);
 me=stats.student;const next=thresholds[me.level]??me.totalXP,previous=thresholds[me.level-1]??0;const goal=goals[0];const best=list.find(c=>c.completed<c.taskCount)||list[0];
 content.innerHTML=header('YOUR PERSONAL LEARNING HQ',`Welcome back, ${esc(me.firstName)} <span class="wave">✦</span>`,'A little curiosity today. A stronger you tomorrow.',`<span class="date-chip">${icon('calendar-days')}${date(new Date(),'short')}</span>`)+`<div class="dashboard-grid"><div class="dashboard-main"><section class="challenge-hero"><div class="hero-copy"><span class="tag">${icon('sparkles')} ${recommendation?.source==='ai'?'AI-POWERED':'ADAPTIVE'} LEARNING</span><h2>Your next breakthrough<br>is one challenge away.</h2><p>${esc(recommendation?.reason||'Choose a course and keep building your skills, one challenge at a time.')}</p>${recommendation?button('Start My Challenge','#task/'+recommendation.task.id):button('Explore Courses','#courses')}<div class="hero-footnote">${icon('circle-check')} Personal to your progress. At your pace.</div></div><div class="crystal-scene"><div class="crystal"><span></span><span></span><span></span></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="crystal-spark spark-one">✦</span><span class="crystal-spark spark-two">✧</span><div class="crystal-xp">${icon('zap')} LEVEL ${me.level}</div></div></section><section class="stat-grid" aria-label="Learning overview">${[['zap','Total XP',num(me.totalXP),'Every challenge counts','purple'],['flame','Day Streak',me.currentStreak,'Keep your momentum','orange'],['award','Achievements',stats.achievements,'Earned, never given','mint'],['trophy','Weekly Rank',board.me?'#'+board.me.rank:'—','Your place in the league','pink']].map(([i,label,value,desc,color])=>`<article class="stat-card"><div class="stat-icon ${color}">${icon(i)}</div><span>${label}</span><strong>${value}</strong><small>${desc}</small></article>`).join('')}</section><section class="panel"><div class="section-title"><div><h2>Continue your journey</h2><p>Your next chapter is waiting.</p></div><a href="#courses">All courses ${icon('arrow-up-right')}</a></div>${best?`<div class="continue-course"><span class="continue-icon">${icon(best.id==='sql'?'database':'braces')}</span><div><h3>${esc(best.title)}</h3><p>${best.completed} of ${best.taskCount} challenges completed</p>${progress(best.completed,best.taskCount)}</div><a class="icon-button" href="#course/${esc(best.id)}" aria-label="Continue ${esc(best.title)}">${icon('arrow-right')}</a></div>`:'<p>No published courses are available.</p>'}</section><section class="panel"><div class="section-title"><div><h2>Learning momentum</h2><p>Every bit of effort adds up.</p></div><span class="subtle-chip">Last 7 days</span></div><div class="chart-area"><canvas id="weekly-chart" aria-label="XP earned over the last seven days" role="img"></canvas></div></section><section class="panel"><div class="section-title"><h2>Explore something new</h2><a href="#courses">View all ${icon('arrow-up-right')}</a></div><div class="course-grid compact">${list.slice(0,2).map(courseCard).join('')}</div></section></div><aside class="dashboard-rail"><section class="panel level-panel"><div class="section-title"><span class="eyebrow">YOUR LEVEL</span><span class="subtle-chip">${me.level<8?'On the rise':'Mastered'}</span></div><div class="level-medallion">${icon('gem')}<strong>${me.level}</strong></div><h2>${['Beginner','Explorer','Achiever','Trailblazer','Expert','Master','Legend','Champion'][me.level-1]||'Champion'}</h2><p>${num(me.totalXP)} / ${num(next)} XP</p>${progress(me.totalXP-previous,next-previous)}<small>${me.level<8?num(Math.max(0,next-me.totalXP))+' XP to Level '+(me.level+1):'You reached the highest level'}</small></section><section class="panel goal-panel"><div class="section-title"><h2>Daily quest</h2><span class="round-icon orange">${icon('flame')}</span></div>${goal?`<p>${esc(goal.title)}</p><div class="goal-numbers"><strong>${goal.progress}<span> / ${goal.target}</span></strong><span class="xp-label">+${goal.xpReward} XP</span></div>${progress(goal.progress,goal.target)}<div class="goal-dots">${Array.from({length:goal.target},(_,i)=>`<span class="${i<goal.progress?'done':''}">${icon(i<goal.progress?'check':'circle')}</span>`).join('')}</div><small>${goal.completed?'Quest complete. Well played!':'One step closer to your daily win.'}</small>`:'<p>No active goals today.</p>'}</section><section class="panel"><div class="section-title"><h2>Weekly league</h2>${icon('trophy')}</div><div class="mini-league">${board.entries.slice(0,3).map(e=>`<div class="league-row ${e.isMe?'is-me':''}"><span class="rank rank-${e.rank}">${e.rank}</span>${avatar(e)}<div><strong>${esc(e.firstName)} ${e.isMe?'<small>YOU</small>':''}</strong><span>${num(e.xp)} XP</span></div></div>`).join('')}</div><a class="rail-link" href="#leaderboard">View Leaderboard ${icon('arrow-right')}</a></section><section class="panel"><div class="section-title"><h2>Next milestones</h2><a href="#achievements">${icon('arrow-up-right')}</a></div>${achievements.filter(a=>!a.unlockedAt).slice(0,2).map(a=>`<div class="milestone"><span class="milestone-icon">${icon(a.icon)}</span><div><strong>${esc(a.title)}</strong><small>${esc(a.description)}</small></div></div>`).join('')||'<p>You have unlocked every milestone.</p>'}</section></aside></div>`;
 content.insertAdjacentHTML('afterbegin','<section class="show-dashboard-banner" data-user-content><span>✦</span><div><span class="show-eyebrow">УЧЕБНОЕ ТЕЛЕШОУ</span><h2>Лига знаний</h2><p>Выберите героя, выйдите в 3D-студию и сыграйте пять раундов.</p></div><a class="show-primary" href="#show">Войти в студию →</a></section>');
 chart(content.querySelector('#weekly-chart'),'bar',stats.weekly.map(d=>new Intl.DateTimeFormat(locale(),{weekday:'short'}).format(new Date(d.date+'T12:00:00Z'))),[{data:stats.weekly.map(d=>d.xp),backgroundColor:'#8b5cf6',borderRadius:5,barThickness:24}]);charts[charts.length-1].labelDates=stats.weekly.map(d=>d.date);
}
async function coursesPage(content,learning=false){let list=await api('courses');const q=new URLSearchParams(location.hash.split('?')[1]).get('q')||'';if(learning)list=list.filter(c=>c.completed>0);content.innerHTML=header(learning?'YOUR LEARNING PATH':'THE COURSE LIBRARY',learning?'Keep moving forward':'A new skill. A new possibility.',learning?'Pick up your progress and take the next step.':'Small challenges. Big understanding. Choose where you want to grow.')+`<div class="filter-row"><label class="searchbox">${icon('search')}<input id="course-search" aria-label="Filter courses" placeholder="Search courses…" value="${esc(q)}"></label><select id="difficulty-filter" aria-label="Filter by difficulty"><option value="">All difficulties</option><option>EASY</option><option>MEDIUM</option><option>HARD</option></select></div><div class="course-grid" id="course-results"></div>`;const render=()=>{const query=content.querySelector('#course-search').value.toLowerCase(),difficulty=content.querySelector('#difficulty-filter').value;const filtered=list.filter(c=>(c.title+' '+c.description).toLowerCase().includes(query)&&(!difficulty||c.difficulty===difficulty));content.querySelector('#course-results').innerHTML=filtered.length?filtered.map(courseCard).join(''):`<div class="empty-state">${icon('book-open')}<h2>${learning?'Your journey starts here':'No matching courses'}</h2><p>${learning?'Complete your first challenge to begin tracking progress.':'Try another search or difficulty.'}</p>${button('Explore Courses','#courses')}</div>`;hydrate();};render();content.querySelector('#course-search').oninput=render;content.querySelector('#difficulty-filter').onchange=render;}
async function coursePage(content,id){const c=await api('courses/'+encodeURIComponent(id));content.innerHTML=`<a class="back-link" href="#courses">${icon('arrow-left')}Course Library</a>`+header(esc(c.category),esc(c.title),esc(c.description),`<span class="tag">${icon('zap')}${num(c.totalXP)} ${ui('XP TO DISCOVER')}</span>`)+`<div class="course-detail-grid"><section class="level-map">${c.levels.map(l=>`<article class="level-node ${l.isLocked?'locked':''}"><div class="level-node-number">${icon(l.isLocked?'lock':l.completed===l.tasks.length?'check':'flag')}</div><div class="level-node-body"><div class="eyebrow">LEVEL ${l.order} · ${num(l.requiredXP)} XP REQUIRED</div><h2>${esc(l.title)} <span>${esc(l.description)}</span></h2><p>${l.isLocked?'Complete previous levels and meet the XP requirement.':l.completed===l.tasks.length?'Level complete. Great work.':'One challenge at a time. You’ve got this.'}</p><div class="task-nodes">${l.tasks.map((t,i)=>`<a ${l.isLocked?'aria-disabled="true" tabindex="-1"':'href="#task/'+esc(t.id)+'"'} class="task-node ${t.completed?'completed':''}" aria-label="${esc(t.title)}${t.completed?', completed':''}">${icon(l.isLocked?'lock':t.completed?'check':'play')}<small>${i+1}</small></a>`).join('')}</div></div></article>`).join('')}</section><aside class="panel course-overview"><span class="eyebrow">YOUR PROGRESS</span><strong class="large-value">${Math.round(c.completed/(c.taskCount||1)*100)}<small>%</small></strong>${progress(c.completed,c.taskCount)}<p>${c.completed} of ${c.taskCount} challenges complete</p><div class="overview-row">${icon('layers')}<span>${c.levels.length} levels</span></div><div class="overview-row">${icon('clock-3')}<span>${c.estimatedMinutes} minutes</span></div><div class="overview-row">${icon('zap')}<span>${num(c.totalXP)} base XP</span></div><div class="tip-box">${icon('sparkles')}Need a little direction? Adaptive learning recommends a challenge based on your history.</div>${button('Find My Next Challenge','#dashboard')}</aside></div>`;}
async function taskPage(content,id){const session=await post('tasks/'+encodeURIComponent(id)+'/start');activeTask=session;const task=session.task;content.innerHTML=`<a class="back-link" href="#course/${esc(task.level.courseId)}">${icon('arrow-left')}${esc(task.level.course.title)}</a><div class="challenge-toolbar"><span>${ui('Level')} ${task.level.order} / ${esc(task.topic.name)}</span><div><span class="xp-label">${icon('zap')}+${task.xpReward} BASE XP</span><span class="timer">${icon('clock-3')}<b id="timer">${task.timeLimit}</b>s</span></div></div><section class="task-panel panel"><span class="tag">CHALLENGE ${task.order} · ${esc(task.difficulty)}</span><h1 data-learning-content>${esc(task.title)}</h1><p class="question" data-learning-content>${esc(task.question)}</p><form id="answer-form"><fieldset><legend class="visually-hidden">Choose your answer</legend><div class="answer-options">${practiceForm(task)??task.options.map((o,i)=>`<label class="answer-option"><input type="radio" name="answer" value="${esc(o.text)}" required><span class="option-letter">${String.fromCharCode(65+i)}</span><span data-learning-content>${esc(o.text)}</span><span class="option-check">${icon('circle-check')}</span></label>`).join('')}</div></fieldset><div id="answer-result" aria-live="polite"></div><button class="btn btn-primary" type="submit" id="submit-answer">Check Answer ${icon('arrow-right')}</button></form><div class="task-actions"><button id="hint" class="text-button">${icon('lightbulb')}Get a Hint</button><a href="#dashboard">${icon('skip-forward')}Skip for Now</a><button id="report" class="text-button">${icon('flag')}Report</button></div><p class="hint-text" id="hint-text" role="status"></p></section><p class="task-note">${icon('shield-check')}Your answer is checked on the server. Rewards are earned once per challenge.</p>`;
 const started=new Date(session.startedAt).getTime();timer=setInterval(()=>{const remaining=Math.max(0,task.timeLimit-Math.floor((Date.now()-started)/1000));const el=document.querySelector('#timer');if(el)el.textContent=remaining;if(!remaining){clearInterval(timer);toast('Time is up. Start a fresh session to try again.','warning');}},1000);
 content.querySelector('#hint').onclick=async e=>{e.currentTarget.disabled=true;try{const hint=await post('ai/hint',{taskId:task.id});content.querySelector('#hint-text').textContent=hint.text;}catch(err){toast(err.message,'error');}};
 content.querySelector('#report').onclick=()=>{showDialog('Report this challenge',`<form id="report-form"><label>What should we review?<textarea name="message" required minlength="5" maxlength="2000"></textarea></label><button class="btn btn-secondary" type="submit">Send Report</button></form>`);document.querySelector('#report-form').onsubmit=async e=>{e.preventDefault();try{await post('tasks/'+task.id+'/report',{message:new FormData(e.currentTarget).get('message')});document.querySelector('#celebration').close();toast('Report saved for the admin to review.','success');}catch(err){toast(err.message,'error');}};};
 const requestId=createRequestId();content.querySelector('#answer-form').onsubmit=async e=>{e.preventDefault();const submit=content.querySelector('#submit-answer');submit.disabled=true;const answer=practiceAnswer(task,e.currentTarget);const oldLevel=me.level;try{
 const result=await post('tasks/'+task.id+'/attempt',{answer,sessionId:session.sessionId,requestId});clearInterval(timer);me.totalXP=result.totalXP;me.level=result.level;
 content.querySelector('#answer-result').innerHTML=`<div class="answer-feedback ${result.isCorrect?'correct':'wrong'}"><strong>${icon(result.isCorrect?'circle-check':'circle-x')}${result.isCorrect?'Nicely done!':'Not quite. Let’s learn from it.'}</strong>${result.isCorrect?`<p data-learning-content>${esc(result.explanation)}</p>`:''}${result.xpEarned?`<span class="reward-big">+${num(result.xpEarned)} XP</span>`:''}<div>${result.isCorrect?button('Next Challenge','#dashboard'):button('Try Again','#task/'+task.id+'?retry='+Date.now())}${button('Back to Course','#course/'+task.level.courseId,true)}</div></div>`;
 content.querySelectorAll('input[name=answer]').forEach(input=>{input.disabled=true;if(input.checked){const option=input.closest('.answer-option');option.classList.add(result.isCorrect?'answer-correct':'answer-wrong');option.querySelector('.option-check').innerHTML=icon(result.isCorrect?'circle-check':'circle-x');}});content.querySelector('#hint').disabled=true;hydrate();celebrate(result,oldLevel);
 }catch(err){toast(err.message,'error');submit.disabled=false;}};
}
async function achievementsPage(content){const list=await api('achievements');const unlocked=list.filter(a=>a.unlockedAt).length;content.innerHTML=header('YOUR TROPHY ROOM','Effort worth celebrating.',`${unlocked} of ${list.length} achievements unlocked. Every badge tells a story.`)+`<div class="achievement-grid">${list.map(a=>`<article class="panel achievement-card ${a.unlockedAt?'unlocked':'locked'}"><span class="achievement-icon">${icon(a.icon)}</span><span class="subtle-chip">${a.unlockedAt?'UNLOCKED':icon('lock')+' LOCKED'}</span><h2 data-learning-content>${esc(a.title)}</h2><p data-learning-content>${esc(a.description)}</p><span class="xp-label">+${a.xpReward} XP</span>${a.unlockedAt?`<small>${ui('Earned')} ${date(a.unlockedAt)}</small>`:'<small>Keep learning to unlock</small>'}</article>`).join('')}</div>`;}
async function leaderboardPage(content){const params=new URLSearchParams(location.hash.split('?')[1]),period=params.get('period')||'global',page=Number(params.get('page'))||1;const board=await api(`leaderboard?period=${encodeURIComponent(period)}&page=${page}`);content.innerHTML=header('A LITTLE FRIENDLY COMPETITION','Learn together. Rise together.','Your effort belongs here. Find your place in the league.')+`<div class="tabs">${['global','weekly','monthly','seasonal'].map(p=>`<a class="${p===period?'active':''}" href="#leaderboard?period=${p}">${p[0].toUpperCase()+p.slice(1)}</a>`).join('')}</div><section class="panel"><div class="table-responsive"><table class="data-table"><thead><tr><th>Rank</th><th>Learner</th><th>Level</th><th>Achievements</th><th>XP</th></tr></thead><tbody>${board.entries.map(e=>`<tr class="${e.isMe?'is-me':''}"><td><span class="rank rank-${e.rank}">${e.rank}</span></td><td><div class="learner-cell">${avatar(e)}<strong data-user-content>${esc(e.firstName+' '+e.lastName)}</strong>${e.isMe?'<span class="tag">YOU</span>':''}</div></td><td><span class="level-pill">LVL ${e.level}</span></td><td>${icon('award')}${e.achievements}</td><td class="xp-label">${num(e.xp)}</td></tr>`).join('')}</tbody></table></div><div class="pagination-row"><span>${board.total} learners</span>${page>1?`<a href="#leaderboard?period=${period}&page=${page-1}">Previous</a>`:''}${page*20<board.total?`<a href="#leaderboard?period=${period}&page=${page+1}">Next</a>`:''}</div></section>${board.me?`<div class="your-rank">${icon('sparkles')}Your current position: <strong>#${board.me.rank}</strong> · ${num(board.me.xp)} XP</div>`:''}`;}
async function seasonsPage(content){const list=await api('seasons');content.innerHTML=header('A FRESH CHALLENGE','Every season, a new story.','Learn, climb, and earn your place among the academy’s best.')+list.map(s=>{const active=new Date(s.startsAt)<=new Date()&&new Date(s.endsAt)>=new Date();return `<section class="panel season-feature"><div><span class="tag">${icon('orbit')}${active?'SEASON ACTIVE':s.finalizedAt?'SEASON COMPLETE':'UPCOMING SEASON'}</span><h2 data-learning-content>${esc(s.title)}</h2><p data-learning-content>${esc(s.description)}</p><p>${date(s.startsAt)} — ${date(s.endsAt)}</p>${active?button('See Seasonal League','#leaderboard?period=seasonal'):''}</div><div class="season-emblem">${icon('trophy')}</div></section><div class="reward-grid">${s.rewards.map(r=>`<article class="panel"><span class="rank rank-${r.rank}">${r.rank}</span><h3>${esc(r.title)}</h3><p>${esc(r.badge)} badge</p>${s.finalizedAt&&s.students[r.rank-1]?`<strong>${esc(s.students[r.rank-1].student.firstName)} · ${num(s.students[r.rank-1].xp)} XP</strong>`:'<small>Keep learning to claim your place.</small>'}</article>`).join('')}</div>`;}).join('');}
async function statisticsPage(content){const s=await api('statistics');content.innerHTML=header('YOUR LEARNING, IN FOCUS','See how far you’ve come.','Turn your activity into insight. Find your strengths and your next opportunity.',`<button class="btn btn-secondary" id="analyze">${icon('sparkles')}Analyze My Progress</button>`)+`<div class="stat-grid">${[['zap','Total XP',num(s.totalXP)],['circle-check','Tasks Completed',s.completedTasks],['target','Accuracy',s.accuracy+'%'],['flame','Longest Streak',s.student.longestStreak+' days']].map(([i,l,v])=>`<article class="stat-card"><span class="stat-icon purple">${icon(i)}</span><span>${l}</span><strong>${v}</strong></article>`).join('')}</div><div class="analytics-grid"><section class="panel"><div class="section-title"><h2>XP Progress</h2></div><div class="chart-area"><canvas id="xp-chart" role="img" aria-label="Daily XP progress"></canvas></div></section><section class="panel"><div class="section-title"><h2>Weekly Activity</h2></div><div class="chart-area"><canvas id="activity-chart" role="img" aria-label="Daily attempt count"></canvas></div></section><section class="panel"><h2>Topic Performance</h2>${s.topics.length?s.topics.map(t=>`<div class="topic-row"><span>${esc(t.name)}</span><strong>${t.accuracy}%</strong>${progress(t.correct,t.correct+t.wrong)}</div>`).join(''):'<p class="empty-copy">Complete a challenge to discover your topic strengths.</p>'}</section><section class="panel"><h2>Difficulty Performance</h2>${s.difficulties.map(d=>`<div class="topic-row"><span>${d.name} · ${d.attempts} attempts</span><strong>${d.accuracy}%</strong>${progress(d.accuracy,100)}</div>`).join('')}<div class="overview-row">Average score <strong>${s.averageScore}%</strong></div><div class="overview-row">Courses completed <strong>${s.completedCourses}</strong></div></section></div><div id="analysis-result"></div>`;
 content.insertAdjacentHTML('beforeend','<section class="panel show-report-extra" data-user-content><h2>Мои результаты</h2><div class="report-overview"><div><strong>'+s.attempts+'</strong><small>Всего попыток</small></div><div><strong>'+(s.averageTimeSeconds??0)+' с</strong><small>Среднее время ответа</small></div><div><strong>'+esc(s.strongTopic?.name||'Пока нет данных')+'</strong><small>Сильная тема</small></div><div><strong>'+esc(s.weakTopic?.name||'Пока нет данных')+'</strong><small>Тема для практики</small></div></div><div id="show-xp-history"></div></section>');const xpHistory=await api('xp');content.querySelector('#show-xp-history').innerHTML='<h3 style="margin-top:25px;font-size:15px">История XP</h3>'+ (xpHistory.length?'<div class="table-responsive"><table class="data-table"><thead><tr><th>Дата</th><th>Источник</th><th>XP</th></tr></thead><tbody>'+xpHistory.slice(0,30).map(e=>'<tr><td>'+date(e.createdAt)+'</td><td>'+esc({TASK:'Задание',ACHIEVEMENT:'Достижение',STREAK:'Стрик',DAILY_GOAL:'Ежедневная цель'}[e.source]||e.source)+'</td><td>+'+num(e.amount)+'</td></tr>').join('')+'</tbody></table></div>':'<p>Решите первое задание, чтобы начать историю.</p>');const labels=s.weekly.map(d=>d.date.slice(5));chart(content.querySelector('#xp-chart'),'line',labels,[{data:s.weekly.map(d=>d.xp),borderColor:'#a78bfa',backgroundColor:'#8b5cf618',fill:true,tension:.35}]);chart(content.querySelector('#activity-chart'),'bar',labels,[{data:s.weekly.map(d=>d.tasks),backgroundColor:'#78d9bf',borderRadius:5}]);
 content.querySelector('#analyze').onclick=async e=>{e.currentTarget.disabled=true;try{const analysis=await post('ai/analyze');content.querySelector('#analysis-result').innerHTML=`<section class="panel analysis-card"><span class="tag">${icon('sparkles')}LEARNING INSIGHT</span><p>${esc(analysis.analysis?.summary)}</p>${analysis.analysis?.focusTopic?`<strong>${ui('Focus:')} ${esc(analysis.analysis.focusTopic)}</strong>`:''}</section>`;hydrate();}catch(err){toast(err.message,'error');}finally{e.currentTarget.disabled=false;}};
}
async function goalsPage(content){const [goals,streak]=await Promise.all([api('daily-goals'),api('streaks')]);content.innerHTML=header('BUILD YOUR LEARNING HABIT','Today is a good day to grow.','Complete distinct challenges to earn your daily reward. Goals reset at midnight in Asia/Qyzylorda.')+`<div class="analytics-grid">${goals.map(g=>`<section class="panel daily-goal-card"><span class="stat-icon orange">${icon('goal')}</span><h2 data-learning-content>${esc(g.title)}</h2><div class="goal-numbers"><strong>${g.progress} / ${g.target}</strong><span class="xp-label">+${g.xpReward} XP</span></div>${progress(g.progress,g.target)}<p>${g.completed?'Goal achieved. Come back tomorrow for a fresh start.':'Each new completed challenge takes you closer.'}</p>${button(g.completed?'Keep Learning':'Start a Challenge','#dashboard')}</section>`).join('')}<section class="panel daily-goal-card"><span class="stat-icon orange">${icon('flame')}</span><h2>Keep the flame alive</h2><strong class="large-value">${streak.current||0}<small>days</small></strong><p>Longest streak: ${streak.longest||0} days</p><p>Complete at least one new challenge each day.</p></section></div>`;}
async function profilePage(content){const [s,achievements]=await Promise.all([api('statistics'),api('achievements')]);const p=s.student;content.innerHTML=header('YOUR LEARNER IDENTITY','This is your story.','Your skills, your milestones, your next chapter.')+`<section class="panel profile-banner">${avatar(p)}<div><h2 data-user-content>${esc(p.firstName+' '+p.lastName)}</h2><p data-user-content>${esc(p.user.email)}</p><span class="level-pill">LEVEL ${p.level}</span></div><span class="xp-label">${num(p.totalXP)} XP</span></section><div class="analytics-grid"><section class="panel"><h2>Edit Profile</h2><form id="profile-form"><div class="form-row"><label>First name<input name="firstName" value="${esc(p.firstName)}" required maxlength="80"></label><label>Last name<input name="lastName" value="${esc(p.lastName)}" required maxlength="80"></label></div><label>About you<textarea name="bio" maxlength="2000">${esc(p.bio)}</textarea></label><label>Avatar URL (HTTPS)<input name="avatarUrl" type="url" value="${esc(p.avatarUrl)}" placeholder="https://…"></label><button class="btn btn-primary" type="submit">Save Profile ${icon('check')}</button></form></section><section class="panel"><h2>Your Milestones</h2><div class="profile-metrics"><div><strong>${s.completedTasks}</strong><span>Tasks completed</span></div><div><strong>${s.accuracy}%</strong><span>Accuracy</span></div><div><strong>${s.completedCourses}</strong><span>Courses complete</span></div><div><strong>${p.currentStreak}</strong><span>Day streak</span></div></div>${achievements.filter(a=>a.unlockedAt).map(a=>`<div class="milestone"><span class="milestone-icon">${icon(a.icon)}</span><strong>${esc(a.title)}</strong></div>`).join('')||'<p>Your first achievement is waiting.</p>'}</section></div>`;
 content.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{me=await api('students/me',{method:'PUT',body:Object.fromEntries(new FormData(e.currentTarget))});toast('Profile updated.','success');}catch(err){toast(err.message,'error');}finally{b.disabled=false;}};
}
async function settingsPage(content){content.innerHTML=header('MAKE IT YOURS','Your space. Your preferences.','Choose how Ascend feels on this device.')+`<section class="panel settings-panel"><h2>Appearance & Motion</h2><label class="setting-row"><span><strong>Light appearance</strong><small>Switch to a light violet workspace.</small></span><input id="theme-toggle" type="checkbox" ${localStorage.getItem('theme')==='light'?'checked':''}></label><label class="setting-row"><span><strong>Reduce animations</strong><small>Keep interactions simple and quiet.</small></span><input id="motion-toggle" type="checkbox" ${localStorage.getItem('reduceMotion')==='true'?'checked':''}></label><div class="setting-row"><span><strong>Learning day timezone</strong><small>Daily goals and streaks use Asia/Qyzylorda (UTC+5).</small></span>${icon('globe')}</div><div class="setting-row"><span><strong>Account security</strong><small>Request a password reset link to change your password.</small></span><a href="#forgot">Reset Password ${icon('arrow-up-right')}</a></div></section>`;content.querySelector('#theme-toggle').onchange=e=>{localStorage.setItem('theme',e.target.checked?'light':'dark');applyPreferences();};content.querySelector('#motion-toggle').onchange=e=>{localStorage.setItem('reduceMotion',e.target.checked);applyPreferences();};}


const adminTemplates={courses:{title:'',description:'',category:'Development',imageUrl:'',difficulty:'EASY',estimatedMinutes:120,isPublished:false},levels:{courseId:'',title:'',description:'',order:1,requiredXP:0,isLocked:false},topics:{courseId:'',name:'',description:''},tasks:{levelId:'',topicId:'',title:'',description:'',question:'',difficulty:'EASY',taskType:'MULTIPLE_CHOICE',xpReward:100,timeLimit:120,hint:'',correctAnswer:'',explanation:'',order:1,options:['','']},achievements:{code:'',title:'',description:'',icon:'award',condition:'TASKS',target:1,xpReward:300},seasons:{title:'',description:'',startsAt:new Date().toISOString(),endsAt:new Date(Date.now()+86400000*90).toISOString(),rewards:[{rank:1,badge:'GOLD',title:'Champion'}]},'daily-goals':{title:'',target:3,xpReward:200,isActive:true},students:{firstName:'',lastName:'',bio:'',avatarUrl:''}};
async function adminPage(content){const params=new URLSearchParams(location.hash.split('?')[1]),resource=params.get('resource')||'dashboard',page=Number(params.get('page'))||1;const resources=['dashboard','students','courses','levels','topics','tasks','achievements','seasons','daily-goals','reports','settings'];content.innerHTML=header('ACADEMY CONTROL CENTER','Admin Studio','Manage learning content and review real student progress.')+`<div class="tabs admin-tabs">${resources.map(r=>`<a class="${r===resource?'active':''}" href="#admin?resource=${r}">${ui(r.replace('-',' '))}</a>`).join('')}</div><div id="admin-body"><div class="skeleton"></div></div>`;
 const body=content.querySelector('#admin-body'),data=await api(`admin/${resource}?page=${page}`);
 if(resource==='dashboard'){body.innerHTML=`<div class="stat-grid">${[['Students',data.students],['Courses',data.courses],['Attempts',data.attempts],['XP Awarded',num(data.xp)]].map(([l,v])=>`<article class="stat-card"><span>${l}</span><strong>${v}</strong></article>`).join('')}</div><section class="panel"><h2>Challenge Reports</h2>${data.reports.length?data.reports.map(r=>`<div class="notification"><strong>${esc(r.task.title)} · ${esc(r.student.firstName)}</strong><p>${esc(r.message)}</p></div>`).join(''):'<p>No student reports.</p>'}</section>`;return;}
 if(resource==='reports'){body.innerHTML=`<section class="panel"><div class="section-title"><h2>Student Performance</h2><button class="btn btn-secondary" id="export-csv">${icon('download')}Export CSV</button><button class="btn btn-secondary" id="print-report">${icon('printer')}Print / PDF</button></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Learner</th><th>XP</th><th>Level</th><th>Attempts</th><th>Achievements</th><th>Topics</th></tr></thead><tbody>${data.map(s=>`<tr><td>${esc(s.firstName+' '+s.lastName)}</td><td>${num(s.totalXP)}</td><td>${s.level}</td><td>${s._count.attempts}</td><td>${s._count.achievements}</td><td>${esc(s.topicProgress.map(t=>`${t.topic.name}: ${t.correct} correct / ${t.wrong} wrong`).join('; '))}</td></tr>`).join('')}</tbody></table></div></section>`;content.querySelector('#print-report').onclick=()=>print();content.querySelector('#export-csv').onclick=()=>{const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const csv=[['Learner','XP','Level','Streak','Attempts','Achievements'],...data.map(s=>[s.firstName+' '+s.lastName,s.totalXP,s.level,s.currentStreak,s._count.attempts,s._count.achievements])].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='student-performance.csv';a.click();URL.revokeObjectURL(url);};return;}
 if(resource==='settings'){const enabled=data.find(x=>x.key==='aiEnabled')?.value??true;body.innerHTML=`<section class="panel"><h2>AI Settings</h2><p>Provider keys and model are configured through server environment variables. These settings control recommendation behavior.</p><form id="ai-settings"><label class="checkbox"><input name="enabled" type="checkbox" ${enabled?'checked':''}>Enable provider recommendations</label><button class="btn btn-primary" type="submit">Save Setting</button></form></section>`;content.querySelector('#ai-settings').onsubmit=async e=>{e.preventDefault();try{await post('admin/settings',{key:'aiEnabled',value:!!new FormData(e.currentTarget).get('enabled')});toast('AI setting saved.','success');}catch(err){toast(err.message,'error');}};return;}
 const template=adminTemplates[resource];body.innerHTML=`<section class="panel"><div class="section-title"><h2>${ui(resource.replace('-',' '))}</h2>${resource!=='students'?'<button class="btn btn-primary" id="create-record">'+icon('plus')+'Create Record</button>':''}</div><div class="table-responsive"><table class="data-table"><thead><tr><th>Record</th><th>ID</th><th>Actions</th></tr></thead><tbody>${data.items.map((r,i)=>`<tr><td>${esc(r.title||r.name||r.firstName+' '+r.lastName)}</td><td><code>${esc(r.id)}</code></td><td><button class="text-button edit-record" data-index="${i}">${icon('pencil')}Edit</button><button class="text-button delete-record" data-index="${i}">${icon('trash-2')}Delete</button></td></tr>`).join('')}</tbody></table></div><div class="pagination-row"><span>${data.total} records</span>${page>1?`<a href="#admin?resource=${resource}&page=${page-1}">Previous</a>`:''}${page*20<data.total?`<a href="#admin?resource=${resource}&page=${page+1}">Next</a>`:''}</div></section>`;
 function editor(record){const values={...template};if(record)for(const k of Object.keys(values))values[k]=k==='options'?record.options.map(o=>o.text):record[k];if(record)values.id=record.id;
 showDialog((record?'Edit':'Create')+' '+resource.replace('-',' '),`<p>Use the schema fields below. Related course, level and topic IDs are visible in their lists.</p><form id="record-form"><label>Record JSON<textarea data-user-content id="record-json" class="json-editor" spellcheck="false" required>${esc(JSON.stringify(values,null,2))}</textarea></label><div id="record-error" role="alert" class="form-error"></div><button type="submit" class="btn btn-secondary">Save to Database ${icon('check')}</button>${resource==='tasks'?'<button type="button" id="generate-task" class="btn btn-secondary">Generate with AI</button>':''}</form>`);
 document.querySelector('#record-form').onsubmit=async e=>{e.preventDefault();try{await post('admin/'+resource,JSON.parse(document.querySelector('#record-json').value));document.querySelector('#celebration').close();toast('Record saved.','success');await renderRoute();}catch(err){document.querySelector('#record-error').textContent=err.message;}};
 document.querySelector('#generate-task')?.addEventListener('click',async e=>{e.target.disabled=true;try{const draft=JSON.parse(document.querySelector('#record-json').value),generated=await post('admin/ai/generate-task',{topic:draft.topicId,difficulty:draft.difficulty});document.querySelector('#record-json').value=JSON.stringify({...draft,...generated},null,2);}catch(err){document.querySelector('#record-error').textContent=err.message;}finally{e.target.disabled=false;}});
 }
 content.querySelector('#create-record')?.addEventListener('click',()=>editor());content.querySelectorAll('.edit-record').forEach(b=>b.onclick=()=>editor(data.items[b.dataset.index]));content.querySelectorAll('.delete-record').forEach(b=>b.onclick=async()=>{const record=data.items[b.dataset.index];if(!confirm(t('Delete this record and its dependent learning data?')))return;try{await api('admin/'+resource+'/'+record.id,{method:'DELETE'});toast('Record deleted.','success');await renderRoute();}catch(err){toast(err.message,'error');}});
}

async function renderRoute(){const version=++routeVersion;const entryBase=location.hash.slice(1).split(/[?/]/)[0];if(!['show','multiplayer'].includes(entryBase))cancelShowEntryAudio();if(disposePage){const dispose=disposePage;disposePage=null;await dispose();}if(version!==routeVersion)return;clearInterval(timer);charts.forEach(c=>c.destroy());charts=[];const route=(location.hash.slice(1)||'dashboard').split('?')[0],base=route.split('/')[0];
 if(['login','register','forgot','reset'].includes(base)){await authPage(base);return;}
 if(!accessToken){try{await refresh();}catch{clearSession();location.hash='login';return;}}
 try{app.innerHTML=shell(base);wireShell();hydrate();if(!me&&role!=='ADMIN'){const [student,configuration]=await Promise.all([api('students/me'),api('configuration')]);me=student;thresholds=configuration.levelThresholds;}if(version!==routeVersion)return;app.innerHTML=shell(base);wireShell();hydrate();const content=document.querySelector('#content');
 if(role==='ADMIN'&&base!=='admin'&&base!=='settings'){const resource=adminNav.some(([id])=>id===base)?base:'dashboard';location.hash='admin?resource='+resource;return;}
 switch(base){case 'show':{const dispose=await showPage(content,{api,refresh,getToken:()=>accessToken,esc,icon,hydrate,toast,student:me,registerDispose:dispose=>{if(version===routeVersion)disposePage=dispose;else dispose();},onProgress:result=>{if(result){me={...me,totalXP:result.totalXP,level:result.level,currentStreak:result.currentStreak};}}});if(version===routeVersion)disposePage=dispose;else dispose();break;}case 'dashboard':await dashboard(content);break;case 'courses':await coursesPage(content);break;case 'learning':await coursesPage(content,true);break;case 'course':await coursePage(content,route.split('/')[1]);break;case 'task':await taskPage(content,route.split('/')[1]);break;case 'achievements':await achievementsPage(content);break;case 'leaderboard':await leaderboardPage(content);break;case 'seasons':await seasonsPage(content);break;case 'statistics':await statisticsPage(content);break;case 'daily-goals':await goalsPage(content);break;case 'profile':await profilePage(content);break;case 'settings':await settingsPage(content);content.insertAdjacentHTML('beforeend','<section class="panel" data-user-content><h2>3D-шоу · звук и графика</h2>'+settingsMarkup()+'</section>');wireShowSettings(content);break;case 'multiplayer':{const params=new URLSearchParams(location.hash.split('?')[1]);location.replace('#show?mode=online'+(params.get('room')?'&room='+encodeURIComponent(params.get('room')):''));break;}case 'admin':if(role!=='ADMIN')throw Error(t('Admin access is required.'));await adminPage(content);break;default:content.innerHTML=header('PAGE NOT FOUND','Let’s get back on track.','Choose a page from your learning space.',button('Dashboard','#dashboard'));}
 if(version===routeVersion){hydrate();window.scrollTo(0,0);}
 }catch(err){if(version!==routeVersion)return;cancelShowEntryAudio();const content=document.querySelector('#content');if(content)content.innerHTML=`<div class="empty-state">${icon('wifi-off')}<h1>We couldn’t load this page.</h1><p>${esc(err.message)}</p><button class="btn btn-primary" id="retry">Try Again</button></div>`;document.querySelector('#retry')?.addEventListener('click',renderRoute);hydrate();}
}
document.addEventListener('click',event=>{
 if(event.defaultPrevented||event.button!==0||event.ctrlKey||event.metaKey||event.shiftKey||event.altKey||document.body.classList.contains('show-open'))return;
 const link=event.target.closest('a[href]');if(!link||link.hasAttribute('download')||(link.target&&link.target!=='_self'))return;
 const destination=new URL(link.href,location.href),base=destination.hash.slice(1).split(/[?/]/)[0];
 if(destination.origin===location.origin&&destination.pathname===location.pathname&&['show','multiplayer'].includes(base))prepareShowEntryAudio();
});
window.addEventListener('hashchange',renderRoute);window.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();document.querySelector('#global-search')?.focus();}});window.addEventListener('languagechange',()=>{localize();updateDates();document.querySelectorAll('[data-language]').forEach(select=>select.value=localStorage.getItem('language'));});observeTranslations();applyPreferences();renderRoute();
